FEP.GeometricMechanics.weightedNodeDiv_e.statement:
theorem weightedNodeDiv_eq (W : Fin n → Fin n → ℝ) {p : Fin n → ℝ}
    (hp : ∀ i, 0 < p i) (i : Fin n) :
    weightedNodeDiv p W i = nodeDiv W i + ∑ j, (1 - p j / p i) * W j i

FEP.HelmholtzAoNess.aoDecomposition.statement:
theorem aoDecomposition {rate : State → State → ℝ} {law : FiniteLaw State}
    (hSupport : ∀ i, 0 < law i) (i j : State) :
    rate i j = symmetricPart rate law i j + circulationPart rate law i j

FEP.HelmholtzAoNess.circulationNum_skew.statement:
theorem circulationNum_skew {rate : State → State → ℝ}
    {law : FiniteLaw State} (i j : State) :
    circulationNum rate law i j = -circulationNum rate law j i

FEP.HelmholtzAoNess.forceSplit.statement:
theorem forceSplit {rate : State → State → ℝ} {law : FiniteLaw State}
    (hSupport : ∀ i, 0 < law i) {i j : State}
    (hij : 0 < rate i j) (hji : 0 < rate j i) :
    Real.log (law i * rate i j / (law j * rate j i)) =
      aoPotential law j - aoPotential law i +
        Real.log (rate i j / rate j i)

FEP.HelmholtzAoNess.symmetricNum_comm.statement:
theorem symmetricNum_comm {rate : State → State → ℝ}
    {law : FiniteLaw State} (i j : State) :
    symmetricNum rate law i j = symmetricNum rate law j i

